// warnings[] üretir (bkz. internal/domain/calc.go). Aynı organization'a
// ait olmayan bir product_id (olağan dışı bir durum) bilinçli olarak
// ANY($1) yalnızca id listesini taşır -- organization_id ayrıca WHERE'de
// doğrulanır, böylece başka bir firmanın ürünü asla sızmaz.
func (q *Queries) ResolveRecipeProducts(ctx context.Context, arg ResolveRecipeProductsParams) ([]Product, error) {
	rows, err := q.db.Query(ctx, resolveRecipeProducts, arg.Ids, arg.OrganizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Product
	for rows.Next() {
		var i Product
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.NormalizedName,
			&i.Unit,
			&i.UnitPrice,
			&i.Description,
			&i.Category,
			&i.Source,
			&i.SourcePrice,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.OrganizationID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

